
import React from "react";
import { AiOutlineSearch } from "react-icons/ai";
import { Button, SearchIcon } from "../components";
import { useStateContext } from "../contexts/ContextProvider";
import { Input } from "@heroui/react";

const Header = ({
  category,
  title,
  searchAction,
  searchValue,
  searchVisible = false,
  currentColor,
  handleSearch,
  deleteVisible = false,
  handleDelete,
  addButtonVisible = true,
  addButtonTitle, handleAddButtonAction

}) => (
  <div className="mx-5 mb-10 grid grid-cols-1 ">
    <p className="text-lg text-gray-400">{category}</p>
    <p className="text-3xl font-extrabold tracking-tight text-slate-900">
      {title}
    </p>
    {searchVisible && (
      <div className="flex w-full md:w-96 items-center justify-center ">
        <div className="basis-4/5  pr-3  pl-10 justify-center shadow-md shadow-gray-300 ml-20 ">
          <Input
            label="Search"
            variant="bordered"
            placeholder="Enter search text"
            endContent={
              <button className="focus:outline-none" type="button">
                <SearchIcon />
              </button>
            }

            className="max-w-xs"
          />
        </div>
        <div
          onClick={() => { }}
          style={{ backgroundColor: currentColor }}
          className="  px-6 p-2 rounded-md justify-center items-center hover:cursor-pointer hover:opacity-60"
        >
          <span className="basis-1/5 text-center">
            <AiOutlineSearch className="text-white text-2xl" />
          </span>
        </div>

      </div>
    )}
    {addButtonVisible && <Button text={addButtonTitle} className=" md:m-1 h-12 w-md  md:max-w-xs  rounded-md" onClick={handleAddButtonAction} />}
    {deleteVisible && <button onClick={handleDelete} className="w-3/12 h-12 bg-red-600 hover:bg-gray-300 cursor-pointer">Delete</button>}

  </div>
);

export default Header;
