import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import {
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  useDisclosure,
  Checkbox,
  Input,
  Link,
  Textarea,
  Switch,
} from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSwitch,
  Loading,
} from "../../../../components";
import { useFormik } from "formik";
import useApi from "../../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import discountsApi from "../../../../api/discountsApi";

import { DatePicker, Modal, Space } from "antd";
import locale from "antd/es/date-picker/locale/en_US";
import dayjs from "dayjs";
import "dayjs/locale/en-gb";

export default function QuantityDiscountsFormModal({
  ismodalOpen,
  setisModalOpen,
  quantityDiscountToEdit,
  modalTitle = "Add new price discount",
  updated,
  setUpdated,
}) {
  // const { isOpen, onOpen, onOpenChange } = useDisclosure();
  const moment = require("moment");

  const [quantityDiscount, setQuantityDiscounts] = useState(
    quantityDiscountToEdit ? quantityDiscountToEdit : null
  );
  const [switchLabel, setswitchLabel] = useState("Activate");
  const [switchStatus, setswitchStatus] = useState(
    quantityDiscountToEdit && quantityDiscountToEdit.is_active === "true"
      ? true
      : false
  );
  const [errors, setErrors] = useState();
  const discountsActionsApi = useApi(discountsApi.quantityDiscountsAction);

  const handleQuantityDiscountAction = async (data) => {
    const result = await discountsActionsApi.request(data);

    console.log("result", result);

    if (result.ok) {
      setUpdated(true);
      setisModalOpen(setUpdated);
    } else {
      if (result.data.errors) {
        setErrors(result.data.errors);
      }
      setUpdated(false);
    }
  };

  useEffect(() => {}, [quantityDiscount]);

  useEffect(() => {
    if (discountsActionsApi.data) {
      if (discountsActionsApi.data.wholesaler_quantity_discount) {
        setQuantityDiscounts(discountsActionsApi.data.wholesaler_quantity_discount);
        setisModalOpen(false)
      }
    }
  }, [discountsActionsApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const formik = useFormik({
    initialValues: {
      start:  quantityDiscount ? quantityDiscount.start : dayjs().format("YYYY-MM-DD"),
      end:  quantityDiscount ? quantityDiscount.end : dayjs().format("YYYY-MM-DD"),
      title: quantityDiscount ? quantityDiscount.title : "",
      limit_quantity: quantityDiscount ? quantityDiscount.limit_quantity : 0,
      awarded_quantity: quantityDiscount
        ? quantityDiscount.awarded_quantity
        : 0,
      is_active: quantityDiscount ? quantityDiscount.is_active : "false",
    },

    validationSchema: Yup.object({
      title: Yup.string()
        .min(3, "Must be 15 characters or more")
        .required("Title is required"),
      awarded_quantity: Yup.number()
        .required()
        .min(1)
        .label("Awarded quantity"),
      limit_quantity: Yup.number().required().min(1).label("Limit quantity"),
      is_active: Yup.bool().label("Status"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      if (quantityDiscount) {
        handleQuantityDiscountAction({
          action: "UpdateQuantityDiscount",
          quantity_discount_details: {
            id: quantityDiscount.id,
            title: values.title,
            limit_quantity: values.limit_quantity,
            awarded_quantity: values.awarded_quantity,
            start: values.start,
            end: values.end,
            is_active: values.is_active,
          },
        });
      } else {
        handleQuantityDiscountAction({
          action: "CreateQuantityDiscount",
          quantity_discount_details: {
            title: values.title,
            limit_quantity: values.limit_quantity,
            awarded_quantity: values.awarded_quantity,
            start: values.start,
            end: values.end,
            is_active: values.is_active,
          },
        });
      }

      // resetForm();
    },
  });
  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };
  const handleStartDateChange = (date, dateString) => {
    formik.setFieldValue("start", dateString);
  };
  const handleEndDateChange = (date, dateString) => {
    formik.setFieldValue("end", dateString);
  };

  const handleSwitchChange = (e) => {
    setswitchStatus(e === true);
    if (e === true) {
      formik.setFieldValue("is_active", "true");
      setswitchLabel("Deactivate");
    } else if (e === false) {
      formik.setFieldValue("is_active", "false");
      setswitchLabel("Activate");
    } else {
      formik.setFieldValue("is_active", "");
    }

    console.log("eee", e);
  };


  return (
    <div className="w-full">
      <Modal
        width={720}
        className="w-full text-center"
        title={modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
          >
            <CustomInput
              required={true}
              label="Enter title"
              id="title"
              name="title"
              onChange={formik.handleChange}
              placeholder="Enter title"
              size="large"
              type="text"
              value={formik.values.title}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.limit_quantity}
            error={formik.errors.limit_quantity}
          >
            <CustomInput
              required={true}
              label="Enter limit_quantity"
              id="limit_quantity"
              name="limit_quantity"
              onChange={formik.handleChange}
              placeholder="Enter limit_quantity"
              size="large"
              type="number"
              value={formik.values.limit_quantity}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.awarded_quantity}
            error={formik.errors.awarded_quantity}
          >
            <CustomInput
              required={true}
              label="Enter awarded quantity"
              id="awarded_quantity"
              name="awarded_quantity"
              onChange={formik.handleChange}
              placeholder="Enter awarded quantity"
              size="large"
              type="number"
              value={formik.values.awarded_quantity}
            />
          </CustomFormItem>
          <CustomFormItem
          touched={formik.touched.preparation_date}
          error={formik.errors.preparation_date}
        >
          <CustomDatePicker
            id="start"
            name="start"
            size="large"
            defaultValue={dayjs(
              formik.values.start,
              "YYYY-MM-DD"
            )}
            placeholder="Select start date"
            onChange={handleStartDateChange}
            value={formik.values.start}
            label="Select start date"
          />
        </CustomFormItem>


          <CustomFormItem
          touched={formik.touched.end}
          error={formik.errors.end}
        >
          <CustomDatePicker
            id="end"
            name="end"
            size="large"
            defaultValue={dayjs(
              formik.values.end,
              "YYYY-MM-DD"
            )}
            placeholder="Select end date"
            onChange={handleEndDateChange}
            value={formik.values.end}
            label="Select end date"
          />
        </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.is_active}
            error={formik.errors.is_active}
          >
            <CustomSwitch
              id="is_active"
              checked={formik.values.is_active === "true"}
              onChange={(e) => handleSwitchChange(e)}
              title={switchLabel}
            />
          </CustomFormItem>
          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
